{"type":"item.completed","item":{"id":"item_1","type":"agent_message","text":"{\"tool\":\"sql_query\",\"arguments\":{\"company_name\":\"CLOSE_fin_01\",\"table_name\":\"ledger\",\"query\":\"WITH ranked AS (SELECT kind,event_key,invoice_id,vendor,business_date,revision,status,amount_minor,currency,due_date,discount_until,terms_code,discount_bps,fx_num,fx_den,ROW_NUMBER() OVER (PARTITION BY kind,event_key ORDER BY revision DESC) AS rn FROM ledger WHERE business_date <= '2026-10-23' AND recorded_at <= '2026-10-24T12:00:00'), active AS (SELECT kind,event_key,invoice_id,vendor,business_date,status,amount_minor,currency,due_date,discount_until,terms_code,discount_bps,fx_num,fx_den FROM ranked WHERE rn=1 AND status <> 'void'), balances AS (SELECT i.event_key,i.business_date,i.currency,i.discount_until,i.terms_code,i.amount_minor-COALESCE((SELECT SUM(p.amount_minor) FROM active p WHERE p.kind IN ('payment','credit') AND p.status='active' AND p.invoice_id=i.event_key AND p.currency=i.currency),0) AS balance,COALESCE((SELECT SUM(h.amount_minor) FROM active h WHERE h.kind='hold' AND h.status='active' AND h.invoice_id=i.event_key AND h.currency=i.currency),0) AS held FROM active i WHERE i.kind='invoice' AND i.status='active' AND i.vendor='BLUE' AND i.due_date <= '2026-10-30'), amounts AS (SELECT event_key,business_date,currency,discount_until,terms_code,CASE WHEN balance <= 0 THEN 0 WHEN balance-held <= 0 THEN 0 ELSE balance-held END AS unheld FROM balances), matched AS (SELECT i.event_key,i.unheld,i.discount_until,t.discount_bps,f.fx_num,f.fx_den FROM amounts i JOIN active t ON t.kind='terms' AND t.status='active' AND t.terms_code=i.terms_code AND t.business_date <= i.business_date JOIN active f ON f.kind='fx' AND f.status='active' AND f.currency=i.currency AND f.business_date <= i.business_date WHERE NOT EXISTS (SELECT 1 FROM active t2 WHERE t2.kind='terms' AND t2.status='active' AND t2.terms_code=i.terms_code AND t2.business_date <= i.business_date AND t2.business_date > t.business_date) AND NOT EXISTS (SELECT 1 FROM active f2 WHERE f2.kind='fx' AND f2.status='active' AND f2.currency=i.currency AND f2.business_date <= i.business_date AND f2.business_date > f.business_date)), fractions AS (SELECT event_key,unheld,discount_bps,fx_num,fx_den,unheld*CASE WHEN '2026-10-23' <= discount_until THEN 10000-discount_bps ELSE 10000 END*fx_num AS numerator,10000*fx_den AS denominator FROM matched), rounded AS (SELECT event_key,unheld,discount_bps,fx_num,fx_den,CAST((numerator-(numerator % denominator))/denominator AS BIGINT)+CASE WHEN 2*(numerator % denominator) >= denominator THEN 1 ELSE 0 END AS usd_cents FROM fractions) SELECT event_key,unheld,discount_bps,fx_num,fx_den,usd_cents,SUM(usd_cents) OVER () AS total_usd_cents FROM rounded ORDER BY event_key\"}}"}}
